 20	type (
 21		// ProxyConfig defines the config for Proxy middleware.
 22		ProxyConfig struct {
 23			// Skipper defines a function to skip middleware.
 24			Skipper Skipper
 25	
 26			// Balancer defines a load balancing technique.
 27			// Required.
 28			Balancer ProxyBalancer
 29	
 30			// Rewrite defines URL path rewrite rules. The values captured in asterisk can be
 31			// retrieved by index e.g. $1, $2 and so on.
 32			// Examples:
 33			// "/old":              "/new",
 34			// "/api/*":            "/$1",
 35			// "/js/*":             "/public/javascripts/$1",
 36			// "/users/*/orders/*": "/user/$1/order/$2",
 37			Rewrite map[string]string
 38	
 39			// RegexRewrite defines rewrite rules using regexp.Rexexp with captures
 40			// Every capture group in the values can be retrieved by index e.g. $1, $2 and so on.
 41			// Example:
 42			// "^/old/[0.9]+/":     "/new",
 43			// "^/api/.+?/(.*)":    "/v2/$1",
 44			RegexRewrite map[*regexp.Regexp]string
 45	
 46			// Context key to store selected ProxyTarget into context.
 47			// Optional. Default value "target".
 48			ContextKey string
 49	
 50			// To customize the transport to remote.
 51			// Examples: If custom TLS certificates are required.
 52			Transport http.RoundTripper
 53	
 54			// ModifyResponse defines function to modify response from ProxyTarget.
 55			ModifyResponse func(*http.Response) error
 56		}
 57	
 58		// ProxyTarget defines the upstream target.
 59		ProxyTarget struct {
 60			Name string
 61			URL  *url.URL
 62			Meta echo.Map
 63		}
