 65		// ProxyBalancer defines an interface to implement a load balancing technique.
 66		ProxyBalancer interface {
 67			AddTarget(*ProxyTarget) bool
 68			RemoveTarget(string) bool
 69			Next(echo.Context) *ProxyTarget
 70		}
 71	
 72		commonBalancer struct {
 73			targets []*ProxyTarget
 74			mutex   sync.RWMutex
 75		}
 76	
 77		// RandomBalancer implements a random load balancing technique.
 78		randomBalancer struct {
 79			*commonBalancer
 80			random *rand.Rand
 81		}
 82	
