package middleware

import (
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"

	"github.com/labstack/echo/v4"
)

func TestProxyBalancerWithNoTargets(t *testing.T) {
	// Next must return nil (no panic) when there are no targets.
	for name, b := range map[string]ProxyBalancer{
		"random-nil":       NewRandomBalancer(nil),
		"random-empty":     NewRandomBalancer([]*ProxyTarget{}),
		"roundrobin-nil":   NewRoundRobinBalancer(nil),
		"roundrobin-empty": NewRoundRobinBalancer([]*ProxyTarget{}),
	} {
		if got := b.Next(nil); got != nil {
			t.Errorf("%s: Next() = %v, want nil", name, got)
		}
		// call twice to make sure round robin modulo does not blow up
		if got := b.Next(nil); got != nil {
			t.Errorf("%s: Next() second call = %v, want nil", name, got)
		}
	}

	// balancer emptied via RemoveTarget must also return nil
	u, _ := url.Parse("http://127.0.0.1:12345")
	rb := NewRandomBalancer([]*ProxyTarget{{Name: "t", URL: u}})
	if !rb.RemoveTarget("t") {
		t.Fatal("could not remove target")
	}
	if got := rb.Next(nil); got != nil {
		t.Errorf("random after remove: Next() = %v, want nil", got)
	}
	rrb := NewRoundRobinBalancer([]*ProxyTarget{{Name: "t", URL: u}})
	if !rrb.RemoveTarget("t") {
		t.Fatal("could not remove target")
	}
	if got := rrb.Next(nil); got != nil {
		t.Errorf("roundrobin after remove: Next() = %v, want nil", got)
	}

	// Proxy middleware must not panic and must return an error (503) with no targets.
	for name, b := range map[string]ProxyBalancer{
		"random":     NewRandomBalancer(nil),
		"roundrobin": NewRoundRobinBalancer(nil),
	} {
		e := echo.New()
		e.Use(Proxy(b))
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		if rec.Code != http.StatusServiceUnavailable {
			t.Errorf("%s: status = %d, want %d", name, rec.Code, http.StatusServiceUnavailable)
		}

		// direct handler call: error must be returned, not a panic
		e2 := echo.New()
		req2 := httptest.NewRequest(http.MethodGet, "/", nil)
		rec2 := httptest.NewRecorder()
		c := e2.NewContext(req2, rec2)
		h := Proxy(b)(func(c echo.Context) error { return nil })
		if err := h(c); err != echo.ErrServiceUnavailable {
			t.Errorf("%s: handler err = %v, want %v", name, err, echo.ErrServiceUnavailable)
		}
	}

	// websocket-ish request path must not panic either
	e := echo.New()
	e.Use(Proxy(NewRandomBalancer(nil)))
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	req.Header.Set(echo.HeaderUpgrade, "websocket")
	req.Header.Set(echo.HeaderConnection, "Upgrade")
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	if rec.Code != http.StatusServiceUnavailable {
		t.Errorf("websocket: status = %d, want %d", rec.Code, http.StatusServiceUnavailable)
	}
}

