var zzPat = []string{"/", "/a", "/a/b", "/:id", "/a/:id", "/a/:id/b", "/*", "/a/*", "/a/:id/*", "/:id/b", "/a/:id/:x", "/x/y/z", "/a/b/c", "/a/b/:id", "/:id/:x", "/:id/*", "/a/b/c/d"}

