func zzSegMatch(ps, hs []string) bool {
	if len(hs) < len(ps) {
		return false
	}
	for i := range ps {
		if strings.HasPrefix(ps[i], ":") {
			if hs[i] == "" {
				return false
			}
		} else if ps[i] != hs[i] {
			return false
		}
	}
	return true
}

func zzMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if strings.HasSuffix(pattern, "*") {
		base := pattern[:len(pattern)-1]
		if base == "/" {
			return strings.HasPrefix(path, "/")
		}
		if !strings.HasSuffix(base, "/") {
			return false
		}
		// static part before first param must be a literal prefix of path
		staticPart := base
		if i := strings.IndexByte(base, ':'); i >= 0 {
			staticPart = base[:i]
		}
		if !strings.HasPrefix(path, staticPart) {
			return false
		}
		ps := strings.Split(base[1:len(base)-1], "/")
		hs := strings.Split(path[1:], "/")
		if len(hs) < len(ps)+1 {
			return false
		}
		return zzSegMatch(ps, hs)
	}
	ps := strings.Split(pattern[1:], "/")
	hs := strings.Split(path[1:], "/")
	if len(ps) != len(hs) {
		return false
	}
	return zzSegMatch(ps, hs)
}

func zzCheck(t *testing.T, routes []string, path, method string, wantErr error) {
	e := New()
	for _, p := range routes {
		e.Add(http.MethodGet, p, func(c Context) error { return nil })
	}
	defer func() {
		if r := recover(); r != nil {
			t.Errorf("PANIC routes=%v path=%q method=%s: %v", routes, path, method, r)
		}
	}()
	c := e.NewContext(nil, nil)
	e.router.Find(method, path, c)
	h := c.Handler()
	if h == nil {
		t.Errorf("NIL handler routes=%v path=%q method=%s", routes, path, method)
		return
	}
	err := h(c)
	if err != wantErr {
		t.Errorf("MISMATCH routes=%v path=%q method=%s: got err=%v want %v (matched path=%q pnames=%v)", routes, path, method, err, wantErr, c.Path(), c.ParamNames())
	}
}

func zzExpect(routes []string, path string, method string) error {
	matched := false
	for _, p := range routes {
		if zzMatch(p, path) {
			matched = true
			break
		}
	}
	if !matched {
		return ErrNotFound
	}
	if method == http.MethodGet {
		return nil
	}
	return ErrMethodNotAllowed
}

func TestZZOracle(t *testing.T) {
	paths := zzPth
	for _, a := range zzPat {
		for _, p := range paths {
			zzCheck(t, []string{a}, p, http.MethodGet, zzExpect([]string{a}, p, http.MethodGet))
			zzCheck(t, []string{a}, p, http.MethodPost, zzExpect([]string{a}, p, http.MethodPost))
		}
	}
	for _, a := range zzPat {
		for _, b := range zzPat {
			for _, p := range paths {
				rs := []string{a, b}
				zzCheck(t, rs, p, http.MethodGet, zzExpect(rs, p, http.MethodGet))
				zzCheck(t, rs, p, http.MethodPost, zzExpect(rs, p, http.MethodPost))
			}
		}
	}
	fmt.Println("oracle done")
}

