}

func TestZZReach(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	for it := 0; it < 20000; it++ {
		n := 1 + rnd.Intn(4)
		routes := make([]string, n)
		for i := range routes {
			routes[i] = zzPool2[rnd.Intn(len(zzPool2))]
		}
		e := New()
		for _, p := range routes {
			e.Add(http.MethodGet, p, func(c Context) error { return nil })
		}
		for _, p := range routes {
			c := e.NewContext(nil, nil)
			e.router.Find(http.MethodGet, p, c)
			if c.Path() != p {
				t.Errorf("route %q unreachable in routes=%v: Find returned path=%q (handler=%v)", p, routes, c.Path(), c.Handler() != nil)
				return
			}
		}
	}
	fmt.Println("reach done")
}
EOF
