// concrete path for a route pattern: params -> v1, v2..., * -> rest
func zzConcrete(pattern string) string {
	segs := strings.Split(pattern[1:], "/")
	out := make([]string, 0, len(segs))
	pi := 0
	for _, s := range segs {
		switch {
		case s == "*":
			out = append(out, "rest")
		case strings.HasPrefix(s, ":"):
			pi++
			out = append(out, fmt.Sprintf("v%d", pi))
		default:
			out = append(out, s)
		}
	}
	return "/" + strings.Join(out, "/")
}

